import itertools
import json

def solve():
    # Houses are numbered left to right
    houses = [1, 2, 3, 4]

    # Attributes (must match puzzle)
    names = ["Peter", "Arnold", "Eric", "Alice"]
    pets = ["bird", "fish", "dog", "cat"]

    solutions = []

    for name_pos in itertools.permutations(houses):
        name_to_house = dict(zip(names, name_pos))

        # Clue 2: Eric is not in the first house.
        if name_to_house["Eric"] == 1:
            continue

        # Clue 5: Alice is not in the first house.
        if name_to_house["Alice"] == 1:
            continue

        for pet_pos in itertools.permutations(houses):
            pet_to_house = dict(zip(pets, pet_pos))

            # Clue 3: Eric keeps a pet bird.
            if name_to_house["Eric"] != pet_to_house["bird"]:
                continue

            # Clue 6: Arnold has fish.
            if name_to_house["Arnold"] != pet_to_house["fish"]:
                continue

            # Clue 4: One house between fish and Peter.
            if abs(pet_to_house["fish"] - name_to_house["Peter"]) != 2:
                continue

            # Clue 1: Dog owner is somewhere to the right of Alice.
            if pet_to_house["dog"] <= name_to_house["Alice"]:
                continue

            # Valid solution found
            house_to_name = {v: k for k, v in name_to_house.items()}
            house_to_pet = {v: k for k, v in pet_to_house.items()}

            solutions.append((house_to_name, house_to_pet))

    # Assuming a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # Still output the first but ensure determinism
        pass

    house_to_name, house_to_pet = solutions[0]

    header = ["House", "name", "pet"]
    rows = []
    for h in sorted(houses):
        rows.append([str(h), house_to_name[h], house_to_pet[h]])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
